import test from'node:test';import assert from'node:assert/strict';import{readFileSync,writeFileSync,chmodSync,renameSync}from'node:fs';import{createHash}from'node:crypto';
import{acquireOriginalWalletAccountInitialSource,isOriginalWalletAccountInitialSource}from'./src/original-policy-supplier/account-initial-source.mjs';
import{acquireOriginalWalletAccountInitialSource as noRelease}from'./src/original-policy-supplier/account-initial-source-no-release.mjs';
import{reset,calls}from'./src/mock-initial-https.mjs';import{encodePQRegistrationIntent}from'@ynx-chain/wallet-auth/pq-wallet-authorization';
const f=JSON.parse(readFileSync(new URL('./fixture.json',import.meta.url))),release=JSON.parse(readFileSync(new URL('./test-release.json',import.meta.url))),genesis=Buffer.from('PUBLIC TEST GENESIS ONLY NOT ADMITTED'),hash=b=>createHash('sha256').update(b).digest('hex');
function r(action='sign'){
 const now=Date.now();return{version:1,kind:'account-initial',action,purpose:'TX-BATCH',networkId:f.expected.chainId,nativeChainId:'6423',account:f.expected.owner,operationId:'PUBLIC-Source-'+action,origin:'ynx-wallet:local-pq',requestDigest:hash(encodePQRegistrationIntent(f.intent)),intent:{...f.intent},createdAt:new Date(now).toISOString(),expiresAt:new Date(now+20000).toISOString(),dataOnly:true,bootstrapAdmission:false,...(action==='broadcast'?{originalOperationId:'PUBLIC-original',transportHash:f.transportHash,abciTransactionHash:f.abciTransactionHash,executionHeight:f.expected.executionHeight}:{})};
}
function view(){const {accountBefore:v}=JSON.parse(readFileSync(new URL('./comet-fixture.json',import.meta.url)));Object.assign(v,{owner:f.expected.owner,networkId:f.expected.chainId,committedHeight:(BigInt(f.expected.executionHeight)-1n).toString(),executionHeight:f.expected.executionHeight,ledgerNonce:'0',authorizationStatus:'legacy',committedAuthorizationStatus:'legacy',pqSigningEnabled:false,committedPQSigningEnabled:false});Object.assign(v.policy,{networkId:f.expected.chainId,enableAt:'1',records:[]});if(v.policy.revocations)v.policy.revocations=[];return v;}
test('production empty admitted epoch table fails BEFORE files/network and returns same cleanable partial',async()=>{reset(JSON.stringify(view()));let partial;await assert.rejects(noRelease(r()),e=>{partial=e.partial;return e.cause.code==='AUTH_INITIAL_SOURCE_ADMITTED_EPOCH_REQUIRED';});assert.equal(calls(),0);assert.equal(isOriginalWalletAccountInitialSource(partial),false);await partial.close();assert.equal(partial.outcome().closed,true);});
for(const action of['sign','broadcast'])test(`actual independent Source ${action} uses protected original bytes/same-H real parser and own brand with explicit test release`,async()=>{
 reset(JSON.stringify(view()));const owner=await acquireOriginalWalletAccountInitialSource(r(action),action==='broadcast'?Buffer.from(f.wire,'base64url'):null);assert.equal(calls(),1);assert.equal(isOriginalWalletAccountInitialSource(owner),true);const original=owner.readOriginal();assert.equal(original.occupancy.registered,false);assert.equal(original.occupancy.ledgerNonce,'0');assert.equal(original.executionHeight,f.expected.executionHeight);assert.deepEqual(Buffer.from(original.genesisBytes),genesis);original.genesisBytes.fill(0);assert.deepEqual(Buffer.from(owner.copyOriginalGenesisBytes()),genesis);assert.equal(owner.observation().independentFinality,false);await owner.recheck();assert.equal(calls(),2);const close=owner.close();assert.throws(()=>owner.assertCurrent());assert.equal(owner.close(),close);await close;assert.equal(owner.outcome().closed,true);
});
test('non200/no-store/occupied nonce never synthesizes zero account or retries',async()=>{
 for(const extra of [{status:404},{headers:{'content-type':'application/json'}},{body:JSON.stringify({...view(),ledgerNonce:'1'})}]){reset(JSON.stringify(view()),extra);let partial;await assert.rejects(acquireOriginalWalletAccountInitialSource(r()),e=>{partial=e.partial;return true;});assert.equal(calls(),1);assert.equal(isOriginalWalletAccountInitialSource(partial),false);await partial.close();}
});
test('Source refresh at changed H fails closed and preserves original first without replacement',async()=>{
 reset(JSON.stringify(view()));const owner=await acquireOriginalWalletAccountInitialSource(r());const fresh=view();fresh.executionHeight=(BigInt(fresh.executionHeight)+1n).toString();fresh.committedHeight=(BigInt(fresh.committedHeight)+1n).toString();reset(JSON.stringify(fresh));await assert.rejects(owner.recheck());assert.throws(()=>owner.readOriginal());assert.equal(owner.outcome().firstCausePresent,true);assert.equal(owner.outcome().effectRetryAuthorized,false);await owner.close();
});
test('protected file inode/content substitution revokes Source before any subsequent network read',async()=>{
 reset(JSON.stringify(view()));const owner=await acquireOriginalWalletAccountInitialSource(r());const old=release.genesis.path+'.retained';renameSync(release.genesis.path,old);writeFileSync(release.genesis.path,genesis,{mode:0o600,flag:'wx'});chmodSync(release.genesis.path,0o600);assert.throws(()=>owner.assertCurrent());assert.equal(calls(),1);await owner.close();renameSync(old,release.genesis.path);
});
